21	function applyPolicyWideModifiers(policyBasePremium: number): number {
22	  const firstInsuranceSurcharge =
23	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
24	  return policyBasePremium + firstInsuranceSurcharge;
25	}
