27	export function quote(
28	  customer: Customer,
29	  items: readonly Item[],
30	  previousContracts: number,
31	): number {
32	  // Each item is priced by the pricing policy that governs its kind:
33	  // components may form blocks, main items follow the price list.
34	  const mainItems = items.filter((item) => !isComponent(item));
35	  const components = items.filter(isComponent);
36	
37	  const policyBasePremium =
38	    mainItemsBasePremium(mainItems) + componentsBasePremium(components);
39	
40	  return (
41	    applyPolicyWideModifiers(policyBasePremium) +
42	    mainItemsRiskSurcharges(mainItems) +
43	    PROCESSING_FEE
44	  );
45	}
