12	function mainItemBasePremiumOf(item: Item): number {
13	  return MAIN_ITEM_BASE_PREMIUMS[item.type] ?? 0;
14	}
15	
16	export function mainItemsBasePremium(mainItems: readonly Item[]): number {
17	  return mainItems.reduce((sum, item) => sum + mainItemBasePremiumOf(item), 0);
18	}
