20	/** Each main item's risk surcharges scale that item's own base premium. */
21	export function mainItemsRiskSurcharges(mainItems: readonly Item[]): number {
22	  return mainItems.reduce(
23	    (sum, item) => sum + riskSurchargeOf(item, mainItemBasePremiumOf(item)),
24	    0,
25	  );
