1	import type { Item } from "./quote.js";
2	
3	/** A cursed item adds a risk surcharge on its own base premium. */
4	const CURSE_SURCHARGE_RATE = 0.5;
5	
6	/** Highly enchanted items add a risk surcharge on their own base premium. */
7	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
8	const HIGH_ENCHANTMENT_LEVEL = 5;
9	
10	function isCursed(item: Item): boolean {
11	  return item.cursed === true;
12	}
13	
14	function isHighlyEnchanted(item: Item): boolean {
15	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
16	}
17	
18	function riskSurchargeRateOf(item: Item): number {
19	  const curseRate = isCursed(item) ? CURSE_SURCHARGE_RATE : 0;
20	  const enchantmentRate = isHighlyEnchanted(item)
21	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
22	    : 0;
23	  return curseRate + enchantmentRate;
24	}
25	
26	/**
27	 * Item-specific risk surcharges apply to the base premium of the affected
28	 * item, not to the policy base premium.
29	 */
30	export function riskSurchargeOf(item: Item, itemBasePremium: number): number {
31	  return itemBasePremium * riskSurchargeRateOf(item);
32	}
